require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if(in_array($action,['add','update'],true)){
   $title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Completează denumirea.');
   $category=trim($_POST['category']??'Casă')?:'Casă';$d=parse_ro_date($_POST['due_date']??'');$days=max(0,(int)($_POST['remind_days']??14));$notes=trim($_POST['notes']??'')?:null;
   if($action==='add'){$s=$pdo->prepare('INSERT INTO home_reminders(title,category,due_date,remind_days,notes,created_by_member_id) VALUES(?,?,?,?,?,?)');$s->execute([$title,$category,$d,$days,$notes,$memberId]);$id=(int)$pdo->lastInsertId();log_activity($pdo,'home_reminder_added','home_reminder',$id,$title);$message='Elementul a fost adăugat.';}
   else{$id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Element invalid.');$s=$pdo->prepare('UPDATE home_reminders SET title=?,category=?,due_date=?,remind_days=?,notes=? WHERE id=?');$s->execute([$title,$category,$d,$days,$notes,$id]);log_activity($pdo,'home_reminder_updated','home_reminder',$id,$title);$message='Elementul a fost actualizat.';}
  }
  if($action==='done'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE home_reminders SET completed=1 WHERE id=?')->execute([$id]);$message='Marcat ca rezolvat.';}
  if($action==='delete'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT title FROM home_reminders WHERE id=?');$q->execute([$id]);$title=(string)($q->fetchColumn()?:'Mentenanță');$pdo->prepare('DELETE FROM home_reminders WHERE id=?')->execute([$id]);log_activity($pdo,'home_reminder_deleted','home_reminder',$id,$title);$message='Elementul a fost șters.';}
 }catch(Throwable $e){$error=$e->getMessage();}
}
$items=$pdo->query("SELECT h.*,m.name creator FROM home_reminders h LEFT JOIN family_members m ON m.id=h.created_by_member_id WHERE h.completed=0 ORDER BY h.due_date IS NULL,h.due_date,h.id")->fetchAll();
$pageTitle='Casă';$active='more';require __DIR__.'/includes/layout_top.php';
$categories=['Centrală','Asigurare','Aer condiționat','Filtre','Impozit','Casă','Altele'];
